const input = $input.all()[0].json;

const userId = input.userId;
const profile = input.profile || {};
const timestamp = input.timestamp;

// Log the onboarding event
console.log(`[Onboarding] User ${userId} completed profile at ${timestamp}`);
console.log(`Career Goal: ${profile.career_goal}`);
console.log(`Skills: ${(profile.skills || []).join(', ')}`);

// Prepare enrichment data
const enrichment = {
  userId,
  career_goal: profile.career_goal || 'Software Developer',
  skills: profile.skills || [],
  academic_background: profile.academic_background || '',
  github_username: profile.github_username || null,
  pipeline_stage: 'profile_enrichment',
  recommendations: [
    'Complete the AI Career Roadmap',
    'Take the initial skill assessment',
    'Connect your GitHub account for code analysis',
    `Focus on ${profile.career_goal || 'your career goal'} skills`
  ],
  next_steps: [
    { action: 'assessment', priority: 'high', description: 'Take initial MCQ assessment' },
    { action: 'roadmap', priority: 'high', description: 'Review AI-generated career roadmap' },
    { action: 'github', priority: 'medium', description: 'Connect GitHub for code analysis' }
  ]
};

return [{ json: enrichment }];

const input = $input.all()[0].json;

// Simulate logging to Supabase n8n_workflow_logs table
const logEntry = {
  workflow_id: 'onboarding-pipeline',
  trigger_source: 'api/mentor/generate',
  status: 'completed',
  user_id: input.userId,
  payload: input,
  result: {
    recommendations: input.recommendations,
    next_steps: input.next_steps
  },
  triggered_at: new Date().toISOString(),
  completed_at: new Date().toISOString()
};

console.log('[n8n Log]', JSON.stringify(logEntry));

return [{ json: { success: true, message: 'Onboarding pipeline completed', data: logEntry } }];

const input = $input.all()[0].json;
const timestamp = input.timestamp;

console.log(`[Skill Decay] Cron triggered at ${timestamp}`);

// Simulate fetching decayed skills
const decayedSkills = input.decayedSkills || [
  { skill: 'React', user_id: 'demo', last_practiced: '30 days ago', decay_percent: 15 },
  { skill: 'Python', user_id: 'demo', last_practiced: '45 days ago', decay_percent: 25 },
  { skill: 'SQL', user_id: 'demo', last_practiced: '20 days ago', decay_percent: 8 }
];

const notifications = decayedSkills.map(s => ({
  type: 'skill_decay_warning',
  user_id: s.user_id,
  message: `Your ${s.skill} skill has decayed by ${s.decay_percent}%. Practice now to refresh!`,
  skill: s.skill,
  urgency: s.decay_percent > 20 ? 'high' : 'medium'
}));

return [{ json: {
  success: true,
  message: `Processed ${decayedSkills.length} decayed skills`,
  notifications,
  processed_at: new Date().toISOString()
}}];

const input = $input.all()[0].json;

const task = {
  id: input.taskId || 'task-' + Date.now(),
  title: input.title || 'New Task',
  type: input.task_type || 'assignment',
  teacher_id: input.teacherId,
  assigned_to: input.assigned_to || [],
  due_date: input.due_date,
  xp_reward: input.xp_reward || 50
};

console.log(`[Task Assignment] Teacher ${task.teacher_id} assigned "${task.title}"`);

// Build notification payloads for each assigned student/class
const notifications = (task.assigned_to || ['all_students']).map(target => ({
  type: 'task_assigned',
  target,
  task_id: task.id,
  message: `New task: "${task.title}" — ${task.xp_reward} XP reward`,
  due_date: task.due_date,
  priority: input.priority || 'medium'
}));

return [{ json: {
  success: true,
  message: `Task "${task.title}" assigned successfully`,
  task,
  notifications,
  notification_count: notifications.length
}}];

const input = $input.all()[0].json;

const owner = input.owner;
const repo = input.repo;
const userId = input.userId;

console.log(`[GitHub Analysis] Analyzing ${owner}/${repo} for user ${userId}`);

// Build analysis report metadata
const report = {
  repo: `${owner}/${repo}`,
  analyzed_at: new Date().toISOString(),
  user_id: userId,
  pipeline_actions: [
    { step: 'fetch_repo_metadata', status: 'completed' },
    { step: 'analyze_code_structure', status: 'completed' },
    { step: 'generate_ai_review', status: 'completed' },
    { step: 'cache_results', status: 'completed' },
    { step: 'update_skill_profile', status: 'completed' }
  ],
  skill_updates: [
    'Updated proficiency for detected languages',
    'Refreshed last_practiced timestamp for relevant skills'
  ]
};

return [{ json: {
  success: true,
  message: `GitHub analysis pipeline completed for ${owner}/${repo}`,
  report
}}];

const input = $input.all()[0].json;

const topic = input.topic;
const userId = input.userId;
const assessmentType = input.type;

console.log(`[Course Enrichment] Enriching content for topic: ${topic}, type: ${assessmentType}`);

// Simulate finding supplementary resources
const enrichment = {
  topic,
  user_id: userId,
  supplementary_resources: [
    { type: 'video', title: `${topic} Crash Course`, source: 'YouTube', url: `https://youtube.com/results?search_query=${encodeURIComponent(topic)}` },
    { type: 'article', title: `Deep Dive into ${topic}`, source: 'MDN/Docs', url: `https://developer.mozilla.org/search?q=${encodeURIComponent(topic)}` },
    { type: 'practice', title: `${topic} Coding Challenge`, source: 'LeetCode', url: `https://leetcode.com/problemset/?search=${encodeURIComponent(topic)}` }
  ],
  coursera_suggestions: [
    { name: `${topic} Fundamentals`, provider: 'Top University' },
    { name: `Applied ${topic}`, provider: 'Industry Expert' }
  ],
  enriched_at: new Date().toISOString()
};

return [{ json: {
  success: true,
  message: `Course enrichment completed for "${topic}"`,
  enrichment
}}];

const input = $input.all()[0].json;

console.log('[Weekly Report] Generating progress report');

// Simulate aggregating weekly stats
const report = {
  report_type: 'weekly_progress',
  generated_at: new Date().toISOString(),
  period: {
    start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(),
    end: new Date().toISOString()
  },
  summary: {
    active_students: 24,
    assessments_completed: 47,
    average_score: 78.5,
    skills_refreshed: 12,
    skills_decayed: 3,
    tasks_completed: 15,
    tasks_pending: 8,
    courses_generated: 5,
    github_repos_analyzed: 7
  },
  top_performers: [
    { student: 'Student A', xp_earned: 450, assessments: 5 },
    { student: 'Student B', xp_earned: 380, assessments: 4 },
    { student: 'Student C', xp_earned: 320, assessments: 3 }
  ],
  recommendations: [
    'Schedule a review session for Python fundamentals (3 students showing decay)',
    'Consider adding more advanced React assessments (high engagement)',
    'GitHub analysis shows strong TypeScript adoption across cohort'
  ]
};

return [{ json: {
  success: true,
  message: 'Weekly progress report generated',
  report
}}];
